// Phase-one starter knowledge for 20 planned Cloudbite roles (docs/cloudbite/expert-pool-100.md §6).
// Every card is original synthesis written for Cloudbite; no source text is quoted or mirrored.
// Evaluation status is unvalidated: these packs are starter knowledge, not an STA-depth corpus.
// Source checkStatus is 'retrieved' only when the URL was actually fetched (checkedAt is that UTC time).

export interface PhaseOneKnowledgePack {
  catalogNumber: number;
  expertId: string;
  name: string;
  domain: string;
  summary: string;
  mission: string;
  questions: string[];
  methods: string[];
  limitations: string[];
  artifacts: Array<{ path: string; label: string; guidance: string }>;
  tools: string[];
  instructions: string;
  version: string;
  cards: Array<{ id: string; term: string; summary: string; match: string[]; roles: string[]; source_ids: string[]; kind: string; tool_scope: string; provenance: string }>;
  sources: Array<{ id: string; title: string; url: string; access: string; license: string; download_policy: string; aliases: string[]; tool_scope: string[]; checkedAt: string; checkStatus: 'retrieved' | 'unverified'; checkNote: string }>;
}

type Source = PhaseOneKnowledgePack['sources'][number];
type Card = PhaseOneKnowledgePack['cards'][number];
type CardDraft = Omit<Card, 'roles' | 'provenance'>;

const VERSION = 'phase-one-2026-10-18.1';
const PROVENANCE = 'cloudbite-authored-synthesis 2026-10-18; paraphrased method guidance, no quoted source text; evaluation unvalidated';
const NOT_FETCHED = 'not fetched during authoring yet';
const LINK_ONLY = 'link-only: cite by URL, do not mirror or copy text into workspaces';

// One bounded retrieval batch (10 documents, HTTP GET with redirects) run 2026-10-18; see docs/cloudbite/phase-one-knowledge.md.
// Retrieval confirms the document was reachable and is the named document; it does not confirm every card's reading of it.
